import re

def valid_recipients(addresses):
    result = []
    for address in addresses:
        address = address.strip().lower()
        if re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", address) and address not in result:
            result.append(address)
    return result
